L27_1 = "\228\184\141\233\129\142\229\156\168\233\128\153\231\168\174\230\131\133\230\179\129\228\184\139\239\188\140\233\130\132\230\156\131\230\156\137\228\186\186\232\166\129\233\157\162\232\169\166\229\151\142\239\188\159"
