L26_1.m_Talk_VTN = L27_1
L27_1 = "\228\184\141\232\191\135\230\131\133\229\134\181\229\143\145\229\177\149\230\136\144\231\142\176\229\156\168\232\191\153\228\184\170\230\160\183\229\173\144\239\188\140\232\191\152\228\188\154\230\156\137\228\186\186\232\166\129\233\157\162\232\175\149\229\144\151\239\188\159"
L26_1.m_Talk_SCN = L27_1
L27_1 = "Aber wird es \195\188berhaupt noch jemanden geben, der bereit ist, das Vorstellungsgespr\195\164ch zu machen, nachdem er gesehen hat, was gerade passiert ist?"
